SELECT CASE WHEN rating >= 3.4 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, country, ROUND((100 * SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_singapore, AVG(rating) AS avg_rating FROM suppliers GROUP BY ROLLUP(CASE WHEN rating >= 3.4 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END, country) ORDER BY rating_bucket DESC
